import React from 'react'
import PropTypes from 'prop-types'
import {Link} from 'react-router-dom'

export default function Navbar(props) {
  return (
      <nav className={`navbar navbar-expand-lg navbar-${props.Mode1 ? props.Mode1 : 'light'} bg-${props.Mode1 ? props.Mode1 : 'light'}`}>
  <div className="container-fluid">
    <Link className="navbar-brand" to="/">{props.title}</Link>
    <button className="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#navbarSupportedContent" aria-controls="navbarSupportedContent" aria-expanded="false" aria-label="Toggle navigation">
      <span className="navbar-toggler-icon"></span>
    </button>
    <div className="collapse navbar-collapse" id="navbarSupportedContent">
      <ul className="navbar-nav me-auto mb-2 mb-lg-0">
        <li className="nav-item">
          <Link className="nav-link" aria-current="page" to="/">{props.home}</Link>
        </li>
        <li className="nav-item">
          <Link className="nav-link" to="/About">{props.about}</Link>
        </li>
        
      </ul>
      
      
      <div className={`form-check form-switch text-${props.Mode2 === 'light' ? 'red' : 'light'}`}>
      <input className="form-check-input" type="checkbox" role="switch" id="switchCheckDefault" onClick={props.toggleMode2}/>
      <label className="form-check-label" htmlFor="switchCheckDefault"  style={{color:(props.Mode2 === 'light' ? 'black' : 'red')}}>Enable Red Mode</label>
      </div>
    </div>

      <div className={`form-check form-switch text-${props.Mode1 === 'light' ? 'dark' : 'light'}`}>
      <input className="form-check-input" type="checkbox" role="switch" id="switchCheckDefault" onClick={props.toggleMode1}/>
      <label className="form-check-label" htmlFor="switchCheckDefault">Enable Dark Mode</label>
      </div>

  </div>
</nav>
  )
}

Navbar.prototype = {
    title: PropTypes.string,
    home: PropTypes.string,
    about: PropTypes.string
}

Navbar.defaultProps = {
    title: "TextUtils",
    home: "Home",
    about: "About TextUtils"
}
